/* From Uiverse.io by vinodjangid07 - Tags: button, share, hover effect */
.__UIV_SCOPE__ .Btn {
  width: 145px;
  height: 45px;
  background: linear-gradient(-45deg, #6bc5f8, #cf59e6, #6bc5f8, #cf59e6);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 5px 5px 0px #4dc6d93d;
  background-size: 400% 400%;
}

.__UIV_SCOPE__ .svgContainer {
  width: 45px;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .svgContainer svg {
  width: 16px;
}

.__UIV_SCOPE__ .svgContainer svg path {
  fill: white;
}

.__UIV_SCOPE__ .textContainer {
  width: 100px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 600;
}

.__UIV_SCOPE__ .Btn:hover {
  animation: gradient 5s ease infinite;
}
/* Button's gradient animation */
@keyframes gradient {
  0% {
    background-position: 0 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0 50%;
  }
}
